def is_palindrome(s):
    return s == s[::-1]

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    s = data[0]
    k = int(data[1])

    n = len(s)

    if n % k != 0:
        print("NO")
        return

    length_of_each_palindrome = n // k

    for i in range(0, n, length_of_each_palindrome):
        if not is_palindrome(s[i:i + length_of_each_palindrome]):
            print("NO")
            return

    print("YES")

if __name__ == "__main__":
    main()
